    const users = [
      { id: 1, name: 'Alice' }, // Email removed - sensitive data
      { id: 2, name: 'Bob' },
    ];
    res.json({ 
      data: users,
      pagination: req.pagination 
    });
  }
);

// Example: Get user by ID with input validation
app.get('/users/:id',
  param('id').isInt({ min: 1 }).withMessage('User ID must be a positive integer'),
  validate,
  (req, res) => {
    const userId = parseInt(req.params.id, 10);
    // In real app, fetch from database
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];
