// Improved application with security best practices
// Enhanced error handling and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ======================
// SECURITY MIDDLEWARE
// ======================

// Set security HTTP headers
app.use(helmet());

// Parse JSON bodies with size limit to prevent DoS
app.use(express.json({ limit: '10kb' }));

// Parse URL-encoded bodies
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting - prevent brute force/DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Disable X-Powered-By header (also handled by helmet, but explicit is good)
app.disable('x-powered-by');

// ======================
// REQUEST LOGGING
// ======================

// Simple request logger (consider using 'morgan' in production)
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// ======================
// INPUT VALIDATION HELPER
// ======================

const validate = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map((validation) => validation.run(req)));

    const errors = validationResult(req);
    if (errors.isEmpty()) {
      return next();
    }

    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map((err) => ({
        field: err.path,
        message: err.msg,
      })),
    });
  };
};

// ======================
// ROUTES
// ======================

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

// Users endpoint with optional filtering
app.get(
  '/users',
  validate([
    query('id')
      .optional()
      .isInt({ min: 1 })
      .withMessage('ID must be a positive integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
  ]),
  (req, res) => {
    // Mock user data - in production, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Sanitize output - remove sensitive fields if not authenticated
    // In a real app, check authentication before exposing emails
    const sanitizedUsers = users.map(({ id, name }) => ({ id, name }));

    // Apply filters if provided
    let result = sanitizedUsers;

    if (req.query.id) {
      const id = parseInt(req.query.id, 10);
      result = result.filter((user) => user.id === id);
    }

    if (req.query.limit) {
      const limit = parseInt(req.query.limit, 10);
      result = result.slice(0, limit);
    }

    res.json({
      data: result,
      count: result.length,
    });
  }
);

// ======================
// 404 HANDLER
// ======================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The requested resource ${req.path} was not found`,
  });
});

// ======================
// GLOBAL ERROR HANDLER
// ======================

// Error handling middleware (must have 4 parameters)
app.use((err, req, res, next) => {
  // Log error for debugging (use proper logging in production)
  console.error(`[ERROR] ${new Date().toISOString()}:`, err.message);
  console.error(err.stack);

  // Don't leak error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  // Handle specific error types
  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid JSON payload',
    });
  }

  if (err.type === 'entity.too.large') {
    return res.status(413).json({
      error: 'Payload Too Large',
      message: 'Request body exceeds size limit',
    });
  }

  // Generic error response
  res.status(err.status || 500).json({
    error: isProduction ? 'Internal Server Error' : err.message,
    ...(isProduction ? {} : { stack: err.stack }),
  });
});

// ======================
// SERVER STARTUP
// ======================

const PORT = process.env.PORT || 3000;

// Only start server if not in test mode
if (process.env.NODE_ENV !== 'test') {
  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Graceful shutdown handling
  process.on('SIGTERM', () => {
    console.log('SIGTERM received. Shutting down gracefully...');
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });
  });

  process.on('SIGINT', () => {
    console.log('SIGINT received. Shutting down gracefully...');
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });
  });
}

module.exports = app;

