const app = express();

// ========================
// SECURITY MIDDLEWARE
// ========================

// Set security HTTP headers
app.use(helmet());

// Parse JSON bodies with size limit to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));

// Parse URL-encoded bodies
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting to prevent brute-force/DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Disable X-Powered-By header to prevent fingerprinting
app.disable('x-powered-by');

// ========================
// REQUEST LOGGING (for security auditing)
// ========================

app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  // In production, use a proper logging library like winston or pino
  console.log(`[${timestamp}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// ========================
// INPUT VALIDATION HELPER
// ========================

const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
};

// ========================
// ROUTES
// ========================

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString() 
  });
});

// Users endpoint with optional query parameter validation
app.get('/users', 
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be an integer between 1 and 100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer'),
  ],
  validate,
  (req, res) => {
    // In production, implement proper authentication/authorization
    // before returning user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const limit = parseInt(req.query.limit) || users.length;
    const offset = parseInt(req.query.offset) || 0;

    // Return paginated results
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        total: users.length,
        limit,
        offset
      }
    });
  }
);

// Example POST route with input validation
app.post('/users',
  [
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 2, max: 100 })
      .withMessage('Name must be between 2 and 100 characters')
      .escape(), // Sanitize to prevent XSS
    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Must be a valid email address')
      .normalizeEmail(),
  ],
  validate,
  (req, res) => {
    const { name, email } = req.body;

    // In production: save to database with parameterized queries
    // to prevent SQL injection

    res.status(201).json({
      message: 'User created successfully',
      user: { id: 3, name, email }
    });
  }
);

// ========================
// 404 HANDLER
// ========================

app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: 'The requested resource does not exist'
  });
});

// ========================
// GLOBAL ERROR HANDLER
// ========================

// This must be the last middleware
app.use((err, req, res, next) => {
  // Log the error for debugging (use proper logging in production)
  console.error(`[ERROR] ${new Date().toISOString()}:`, err.stack);

  // Don't leak error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  // Handle specific error types
  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid JSON in request body'
    });
  }

  // Generic error response
  res.status(err.status || 500).json({
    error: isProduction ? 'Internal Server Error' : err.message,
    ...(isProduction ? {} : { stack: err.stack })
  });
});

// ========================
// SERVER STARTUP
// ========================

const PORT = process.env.PORT || 3000;

// Only start server if not in test mode
if (process.env.NODE_ENV !== 'test') {
  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });

  // Graceful shutdown handling
  process.on('SIGTERM', () => {
    console.log('SIGTERM received. Shutting down gracefully...');
    server.close(() => {
      console.log('Server closed.');
      process.exit(0);
    });
  });
}

module.exports = app;

