    uptime: process.uptime(),
  });
});

// Users endpoint with optional query parameter validation
app.get('/users', 
  [
    query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  ],
  handleValidationErrors,
  (req, res) => {
    // In production, this would come from a database
    // Note: Consider what data should be public vs. authenticated
    const users = [
      { id: 1, name: 'Alice' }, // Removed email from public response
      { id: 2, name: 'Bob' },
    ];

    res.json({
      data: users,
      meta: {
        total: users.length,
        page: parseInt(req.query.page) || 1,
        limit: parseInt(req.query.limit) || 10,
      },
    });
  }
);

// Example POST endpoint with input validation
app.post('/users',
  [
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 100 }).withMessage('Name must be between 2 and 100 characters')
      .matches(/^[a-zA-Z\s'-]+$/).withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Invalid email format')
      .normalizeEmail(),
  ],
  handleValidationErrors,
  (req, res) => {
    const { name, email } = req.body;
    // In production: sanitize, validate against DB, etc.
    res.status(201).json({
      message: 'User created successfully',
      data: { id: 3, name }, // Don't echo back sensitive data unnecessarily
    });
  }
);

// ===================
// 404 Handler
// ===================

app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`,
  });
});

// ===================
// Global Error Handler
// ===================

app.use((err, req, res, next) => {
  // Log error for debugging (use proper logging service in production)
  console.error(`[ERROR] ${new Date().toISOString()}:`, err);

  // Don't expose stack traces or internal errors in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: err.status ? err.message : 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ===================
// Server Startup
// ===================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Process terminated.');
    process.exit(0);
  });
});

module.exports = app;
